<#
.SYNOPSIS
    Creates the complete CuredHosting WordPress block theme on disk.

.DESCRIPTION
    This script recreates every file of the "curedhosting" theme:
      - style.css, theme.json, functions.php and all PHP includes
      - Block templates and template parts (header, footer, pages)
      - All content patterns: homepage sections, plan tables, About page,
        Contact, Onboarding form, Migration, Grand Opening landing page,
        and every legal/policy page (Fair Use, Acceptable Use, Banned
        Plugins, Privacy placeholder, Terms placeholder)
      - The real CuredHosting logo (perfectlogo-256.png), the theme
        screenshot, and the fallback logo assets
      - All documentation (README, architecture, checklists, testing guide)

    Every file is embedded as Base64 so it is written byte-for-byte
    identical to the source repository, and each file is verified against
    its SHA-256 hash after writing. No internet connection is required.

    After running, copy (or point -Destination at) your WordPress
    wp-content/themes directory, then activate "CuredHosting" in
    WP Admin -> Appearance -> Themes. Activation automatically installs
    the logo and creates all pages (About, plans, legal pages, etc.).

.PARAMETER Destination
    Directory in which the "curedhosting" theme folder will be created.
    Defaults to the current directory. Example for a LocalWP site:
      .\Create-CuredHostingTheme.ps1 -Destination "C:\Users\you\Local Sites\curedhosting\app\public\wp-content\themes"

.PARAMETER Force
    Overwrite an existing curedhosting folder without prompting.

.EXAMPLE
    .\Create-CuredHostingTheme.ps1
    Creates .\curedhosting with the full theme inside.

.EXAMPLE
    .\Create-CuredHostingTheme.ps1 -Destination "D:\wp\wp-content\themes" -Force

.NOTES
    Compatible with Windows PowerShell 5.1 and PowerShell 7+.
    If script execution is blocked, run:
      powershell -ExecutionPolicy Bypass -File .\Create-CuredHostingTheme.ps1
#>
[CmdletBinding()]
param(
    [string]$Destination = (Get-Location).Path,
    [switch]$Force
)

$ErrorActionPreference = 'Stop'

$ThemeFolderName = 'curedhosting'
$ThemeRoot = Join-Path $Destination $ThemeFolderName

Write-Host ''
Write-Host '  CuredHosting theme generator' -ForegroundColor Green
Write-Host '  ----------------------------' -ForegroundColor Green
Write-Host "  Target: $ThemeRoot"
Write-Host ''

if (Test-Path $ThemeRoot) {
    if (-not $Force) {
        $answer = Read-Host "  '$ThemeRoot' already exists. Overwrite its files? (y/N)"
        if ($answer -notmatch '^[Yy]') {
            Write-Host '  Aborted. Nothing was changed.' -ForegroundColor Yellow
            exit 1
        }
    }
}

