)

$written = 0
$failed  = 0

foreach ($f in $Files) {
    $target = Join-Path $ThemeRoot ($f.Path -replace '/', [IO.Path]::DirectorySeparatorChar)
    $dir = Split-Path $target -Parent
    if (-not (Test-Path $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }

    $bytes = [Convert]::FromBase64String(($f.Data -replace '\s',''))
    [IO.File]::WriteAllBytes($target, $bytes)

    $sha = [BitConverter]::ToString(
        [Security.Cryptography.SHA256]::Create().ComputeHash($bytes)
    ).Replace('-','').ToLowerInvariant()

    if ($sha -eq $f.Sha256) {
        Write-Host ("  [ok] {0}" -f $f.Path)
        $written++
    } else {
        Write-Host ("  [FAILED HASH CHECK] {0}" -f $f.Path) -ForegroundColor Red
        $failed++
    }
}

Write-Host ''
if ($failed -eq 0) {
    Write-Host ("  Done. {0} files written and verified." -f $written) -ForegroundColor Green
    Write-Host ''
    Write-Host '  Next steps:' -ForegroundColor Cyan
    Write-Host "   1. Copy '$ThemeFolderName' into your site's wp-content\themes folder"
    Write-Host '      (or re-run this script with -Destination pointed there).'
    Write-Host '   2. In WP Admin go to Appearance -> Themes and activate CuredHosting.'
    Write-Host '   3. Activation auto-creates all pages (Home, plans, About, Contact,'
    Write-Host '      Onboarding, Migration, Grand Opening, and all legal pages) and'
    Write-Host '      installs the CuredHosting logo.'
    Write-Host '   4. See curedhosting\README.md for the full setup and editing guide.'
} else {
    Write-Host ("  {0} file(s) FAILED verification - the script file may be corrupted. Re-download it." -f $failed) -ForegroundColor Red
    exit 1
}
Write-Host ''
